spec:
flowchart TD
  P["Packet to dst D (locally generated or received)"] --> R{"Policy rules (ip rule)\nselect table(s) in priority order"}
  R --> L{"Lookup D in table:\nlocal → main → default (per rules)"}
  L -- "match (longest prefix, then lowest metric)" --> T{"Route type"}
  L -- "no match in any table" --> N["ENETUNREACH / ICMP net unreachable"]
  T -- "local/broadcast" --> D1["Deliver to this host"]
  T -- "unicast, scope link (connected)" --> D2["ARP/NDP for D itself on dev; send frame"]
  T -- "unicast via G" --> D3["ARP/NDP for G on dev; send frame to G's MAC"]
  T -- "blackhole" --> D4["Drop silently"]
  T -- "unreachable / prohibit" --> D5["Drop + ICMP unreachable / admin prohibited"]

flowchart TD
  S["Can't reach D"] --> A{"ip route get D\nsensible dev, via, src?"}
  A -- "RTNETLINK: Network is unreachable" --> A1["No route: add default/static route; is the NIC up/has address?"]
  A -- "wrong dev / wrong src" --> A2["Metric, duplicate default, overlapping prefix, missing policy rule; fix routes/rules"]
  A -- ok --> B{"Can I reach the next hop?\nip neigh / arping / ping gateway"}
  B -- "neighbour FAILED/INCOMPLETE" --> B1["L2 problem: VLAN, cable, switch port, wrong gateway IP, firewall on ARP"]
  B -- ok --> C{"tcpdump on the egress NIC:\ndo packets leave? replies return?"}
  C -- "leave, no reply" --> C1["Remote/transit problem: gateway has no route back, NAT, firewall, asymmetric path; traceroute/mtr"]
  C -- "reply arrives on another NIC" --> C2["Asymmetric routing: rp_filter, policy routing"]
  C -- "do not leave" --> C3["Local firewall/qdisc/xfrm, source address, MTU (ping -M do), netns confusion"]

flowchart TD
  X["Inside host cannot reach Internet"] --> A{"Has IP, gateway, DNS?\n(DHCP / static)"}
  A -- "no" --> A1["DHCP: tcpdump 67/68, relay, pool, VLAN, rogue server"]
  A -- "yes" --> B{"ping gateway ok?"}
  B -- "no" --> B1["L2/ARP problems (chapter 2.3)"]
  B -- "yes" --> C{"Gateway forwards?\nip_forward, FORWARD policy"}
  C -- "no" --> C1["Enable forwarding; allow in FORWARD chain"]
  C -- "yes" --> D{"tcpdump on outside iface:\nsource translated?"}
  D -- "source still private" --> D1["Missing/incorrect SNAT/masquerade rule (wrong -o, -s); rule order"]
  D -- "translated, no reply" --> D2["Upstream routing/filtering; asymmetric path; wrong outside IP"]
  D -- "reply arrives, not delivered" --> D3["conntrack drop (table full, timeouts), rp_filter, FORWARD rules"]

flowchart TD
  S["Low collective bandwidth / long step time"] --> A{"Any drops on lossless class?"}
  A -- "yes" --> A1["PFC/headroom/ECN mismatch; priority mismatch NIC↔switch; watchdog fired; wrong DSCP mapping"]
  A -- "no" --> B{"PFC pause counters high?"}
  B -- "yes" --> B1["Congestion → PFC: lower ECN thresholds, check load balancing, find the incast victim; storm? find the source port; deadlock?"]
  B -- "no" --> C{"ECN marks / CNPs high?"}
  C -- "yes" --> C1["Congestion handled by DCQCN but constant: hot links, hash collisions, oversubscription; improve LB, check ECMP imbalance"]
  C -- "no" --> D{"Link/NIC errors, MTU, speed?"}
  D -- "yes" --> D1["Optics/CRC errors, degraded link speed, MTU mismatch, wrong lane count"]
  D -- "no" --> E["Software/topology: NCCL config (HCA, GID, TC), CPU/NUMA/PCIe, rail mismatch, slow node (stragglers)"]

flowchart TD
  A["A cannot reach B (service X)"] --> N{"Same on all clients,\nor only A?"}
  N -- "only A" --> AL["A's local config: IP, mask, gateway, DNS, proxy, firewall, VPN, route (ip route get)"]
  N -- "all" --> B{"B up and listening?\nss -tlnp on B; local curl"}
  B -- "no" --> BL["Service/host problem: process, bind address, resources, logs"]
  B -- "yes" --> P{"ping/nc from A\nto B:port"}
  P -- "refused (RST)" --> R1["Firewall reject or wrong port/address"]
  P -- "timeout" --> H["Half-split the path: traceroute/mtr; capture at midpoint and both ends"]
  H --> H1{"SYN reaches B?"}
  H1 -- "no" --> H2["Drop between: ACL, security group, routing, VLAN, ARP, MTU of the SYN"]
  H1 -- "yes, no SYN-ACK back" --> H3["B-side firewall/listen queue/conntrack/rp_filter"]
  H1 -- "SYN-ACK leaves B, not seen by A" --> H4["Return path: asymmetric route, NAT, stateful FW, policy routing"]
  P -- "works" --> APP["Layer 7: DNS, TLS, auth, app config, proxy, MTU for large payloads"]
